int run_main(int argc,char** argv){if(argc!=3){std::cerr<<"Usage: billfish-animation-parser request.json response.json\n";return 2;}J response={{"version",1},{"parserVersion",VERSION}};int result=0;bool responseSafe=true;try{J req=readJson(fs::u8path(argv[1]));if(req.at("version")!=1)throw Failure("INVALID_REQUEST","Unsupported request version");std::string op=req.at("operation");fs::path source=fs::u8path(req.at("source").get<std::string>());if(!source.is_absolute())throw Failure("INVALID_REQUEST","Source must be absolute");fs::path responsePath=fs::u8path(argv[2]);if(samePath(responsePath,source)||insideDirectory(responsePath,source.parent_path())){responseSafe=false;throw Failure("UNSAFE_OUTPUT_PATH","Response cannot overwrite source or be placed in the source directory");}fs::path output;if(op!="inspect"){output=fs::u8path(req.at("output").get<std::string>());if(!output.is_absolute()||samePath(output,source)||insideDirectory(output,source.parent_path()))throw Failure("UNSAFE_OUTPUT_PATH","Output must be absolute and outside the source directory");}Context c(req);J data;if(op=="inspect")data=inspect(c);else if(op=="model")data=model(c,output);else if(op=="clip")data=clip(c,req.at("clipIndex").get<size_t>(),output);else throw Failure("INVALID_REQUEST","Unknown operation");response["ok"]=true;response["data"]=data;}catch(const Failure& e){response["ok"]=false;response["error"]={{"code",e.code},{"message",e.what()},{"details",J::object()}};result=1;}catch(const std::exception& e){response["ok"]=false;response["error"]={{"code","INVALID_REQUEST_OR_DATA"},{"message",e.what()},{"details",J::object()}};result=1;}if(!responseSafe){std::cerr<<response["error"].dump()<<'\n';return 1;}try{writeJson(fs::u8path(argv[2]),response);}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 3;}if(result)std::cerr<<response["error"].dump()<<'\n';return result;}

